"""Academy-only localization for the early multilingual release.

English remains the canonical curriculum/assessment source. Spanish (Latin America)
and Modern Standard Arabic are presentation layers only: IDs, answer keys, scores,
engineering equations, units, product identifiers and specialist-engine ownership do
not change with locale.
"""
from __future__ import annotations

from copy import deepcopy
from typing import Any

from flask import request, session

SUPPORTED_LOCALES = {
    "en": {"label": "English", "native_label": "English", "dir": "ltr", "html_lang": "en"},
    "es-419": {"label": "Spanish", "native_label": "Español", "dir": "ltr", "html_lang": "es-419"},
    "ar": {"label": "Arabic", "native_label": "العربية", "dir": "rtl", "html_lang": "ar"},
}


def normalize_locale(value: object) -> str | None:
    raw = str(value or "").strip().lower().replace("_", "-")
    if raw in SUPPORTED_LOCALES:
        return raw
    if raw.startswith("es"):
        return "es-419"
    if raw.startswith("ar"):
        return "ar"
    if raw.startswith("en"):
        return "en"
    return None


def current_locale() -> str:
    saved = normalize_locale(session.get("academy_locale"))
    if saved:
        return saved
    for language, _quality in request.accept_languages:
        matched = normalize_locale(language)
        if matched:
            return matched
    return "en"


def locale_info(locale: str | None = None) -> dict[str, str]:
    return SUPPORTED_LOCALES[normalize_locale(locale) or current_locale()]


