UI = {"en": UI_EN, "es-419": {**UI_EN, **UI_ES}, "ar": {**UI_EN, **UI_AR}}


def tr(key: str, locale: str | None = None, **values: Any) -> str:
    loc = normalize_locale(locale) or current_locale()
    text = UI.get(loc, UI_EN).get(key, UI_EN.get(key, key))
    try:
        return text.format(**values)
    except (KeyError, ValueError):
        return text


