PHRASES = {"es-419": PHRASES_ES, "ar": PHRASES_AR}


def translate_phrase(value: str, locale: str | None = None) -> str:
    loc = normalize_locale(locale) or current_locale()
    if loc == "en":
        return value
    return PHRASES.get(loc, {}).get(value, value)


def localize(value: Any, locale: str | None = None) -> Any:
    """Deep-copy and translate exact learner-facing strings without touching keys/IDs."""
    loc = normalize_locale(locale) or current_locale()
    if loc == "en":
        return deepcopy(value)
    if isinstance(value, str):
        return translate_phrase(value, loc)
    if isinstance(value, list):
        return [localize(item, loc) for item in value]
    if isinstance(value, tuple):
        return tuple(localize(item, loc) for item in value)
    if isinstance(value, dict):
        return {key: localize(item, loc) for key, item in value.items()}
    return deepcopy(value)


def localize_assessment_result(activity: dict[str, Any], result: dict[str, Any], locale: str | None = None) -> dict[str, Any]:
    """Translate feedback for the response while keeping canonical audit data unchanged."""
    loc = normalize_locale(locale) or current_locale()
    out = deepcopy(result)
    kind = activity.get("kind")
    if kind == "quiz":
        field = "correct_feedback" if result.get("correct") else "incorrect_feedback"
        out["feedback"] = translate_phrase(str(activity.get(field) or out.get("feedback") or ""), loc)
        out["hint"] = None if result.get("correct") else translate_phrase(str(activity.get("hint") or out.get("hint") or ""), loc)
    elif kind == "practical":
        field = "success_feedback" if result.get("correct") else "retry_feedback"
        out["feedback"] = translate_phrase(str(activity.get(field) or out.get("feedback") or ""), loc)
        if not result.get("correct"):
            hints = {
                "es-419": "Sigue la corriente desde residuos grandes → sólidos desestabilizados → remoción de sólidos a granel → filtración fina → protección de membrana → remoción de sales disueltas → barrera de agua producto.",
                "ar": "تتبّع التيار من المخلفات الكبيرة ← زعزعة استقرار المواد الصلبة ← إزالة المواد الصلبة الرئيسية ← الترشيح الدقيق ← حماية الغشاء ← إزالة الأملاح الذائبة ← حاجز المياه المنتجة.",
            }
            out["hint"] = hints.get(loc, out.get("hint"))
    elif kind == "test":
        if loc == "es-419":
            out["feedback"] = "Módulo aprobado. Estás listo para continuar la ruta de aprendizaje." if result.get("correct") else "Revisa los conceptos y el razonamiento práctico y luego intenta nuevamente el examen del módulo."
            out["hint"] = None if result.get("correct") else "Concéntrate en agua de alimentación → propósito de la barrera → protección aguas abajo → objetivo del producto."
        elif loc == "ar":
            out["feedback"] = "تم اجتياز الوحدة. أنت جاهز لمتابعة مسار التعلم." if result.get("correct") else "راجع المفاهيم والمنطق العملي ثم أعد محاولة اختبار الوحدة."
            out["hint"] = None if result.get("correct") else "ركز على مياه التغذية ← غرض الحاجز ← حماية العمليات اللاحقة ← هدف المنتج."
    out["competencies"] = localize(out.get("competencies", []), loc)
    return out


def language_options() -> list[dict[str, str]]:
    return [{"code": code, **info} for code, info in SUPPORTED_LOCALES.items()]
